CREATE TABLE "cases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"title" text NOT NULL,"status" text NOT NULL DEFAULT 'draft',"summary" text,"final_conclusion" text,"confidence" real,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "evidence_assets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"file_path" text NOT NULL,"file_hash" text NOT NULL,"evidence_type" text NOT NULL,"redaction_status" text NOT NULL DEFAULT 'pending',"extraction" jsonb,"uploaded_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "api_traces" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"request_id" text,"trace_id" text,"upstream_request_id" text,"provider" text,"route" text,"channel" text,"model" text,"status_code" integer,"retry" jsonb,"client_request" jsonb,"transformed_request" jsonb,"upstream_response" jsonb,"final_response" jsonb);
CREATE TABLE "extracted_fields" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"evidence_id" uuid REFERENCES "evidence_assets"("id"),"field_name" text NOT NULL,"field_value" text,"confidence" real,"source_coordinates" jsonb,"human_edited" boolean DEFAULT false);
CREATE TABLE "rule_findings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"rule_id" text NOT NULL,"severity" text NOT NULL,"fault_layer" text NOT NULL,"evidence" jsonb,"conclusion" text NOT NULL,"needs_more_evidence" boolean DEFAULT false);
CREATE TABLE "diagnosis_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"model" text,"report" jsonb NOT NULL,"duration_ms" integer,"status" text NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "citations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"diagnosis_id" uuid NOT NULL REFERENCES "diagnosis_runs"("id"),"title" text NOT NULL,"url" text NOT NULL,"vendor" text,"category" text,"excerpt" text);
CREATE TABLE "document_chunks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"title" text NOT NULL,"body" text NOT NULL,"vendor" text NOT NULL,"category" text,"priority" integer DEFAULT 0,"source_url" text NOT NULL,"fetched_at" timestamp,"search_vector" tsvector,"embedding" jsonb);
CREATE TABLE "case_links" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"case_id" uuid NOT NULL REFERENCES "cases"("id"),"linked_case_id" uuid REFERENCES "cases"("id"),"link_type" text NOT NULL,"score" real);
CREATE INDEX "evidence_case_idx" ON "evidence_assets" ("case_id"); CREATE INDEX "trace_case_idx" ON "api_traces" ("case_id"); CREATE INDEX "trace_request_idx" ON "api_traces" ("request_id"); CREATE INDEX "trace_trace_idx" ON "api_traces" ("trace_id"); CREATE INDEX "trace_status_idx" ON "api_traces" ("status_code"); CREATE INDEX "document_chunks_search_idx" ON "document_chunks" USING gin ("search_vector");
